def to_record(row: dict[str, str], unknown_label: str) -> Record:
    """Convert a raw System B row to a Record."""
    try:
        value_date = date.fromisoformat(row["value_date"].strip())
        amount = to_major_units(row["amount"])
    except (ValueError, KeyError) as exc:
        raise LedgerParseError(f"System B conversion error: {exc}") from exc

