def to_record(row: dict[str, str], unknown_label: str) -> Record:
    """Convert a raw System C row to a Record."""
    try:
        date_parts = row["txn_date"].strip().split("/")
        if len(date_parts) != 3:
            raise ValueError(f"invalid date format: {row['txn_date']}")
        day, month, year = int(date_parts[0]), int(date_parts[1]), int(date_parts[2])
        txn_date = date(year, month, day)
        amount = Decimal(row["gross_amount"].strip())
    except (ValueError, KeyError) as exc:
        raise LedgerParseError(f"System C conversion error: {exc}") from exc

    return Record(
        record_id=row["ref"],
        source_system="C",
        date=txn_date,
        account_code=row["ledger_acct"],
        account_name=account_name(row["ledger_acct"], unknown_label),
        description=row["narrative"],
